// uc_unitw8.v (GENERATED by make_unit_v5.py 3, do not edit): uc_unitr8 with the pool hooks (start, entry, ce, abort, dblk; fetching, dmem_act, dmem_ld) around uc_unith8 (ledger #1377).  Needs uc_unith8.v.

// word-RAM digit select (read): lane l of the digit = bit (kk * W + l) of the word, for l < W (width W = 2**lw)
module sc_rdsel8 (input [31:0] w, input [4:0] kk, input [1:0] lw, output [7:0] d);
    reg o0; always @* begin o0 = 1'b0; case (lw) 2'd3: o0 = w[(kk << 3) + 0]; 2'd2: o0 = w[(kk << 2) + 0]; 2'd1: o0 = w[(kk << 1) + 0]; 2'd0: o0 = w[(kk << 0) + 0]; default: o0 = 1'b0; endcase end
    assign d[0] = o0;
    reg o1; always @* begin o1 = 1'b0; case (lw) 2'd3: o1 = w[(kk << 3) + 1]; 2'd2: o1 = w[(kk << 2) + 1]; 2'd1: o1 = w[(kk << 1) + 1]; default: o1 = 1'b0; endcase end
    assign d[1] = o1;
    reg o2; always @* begin o2 = 1'b0; case (lw) 2'd3: o2 = w[(kk << 3) + 2]; 2'd2: o2 = w[(kk << 2) + 2]; default: o2 = 1'b0; endcase end
    assign d[2] = o2;
    reg o3; always @* begin o3 = 1'b0; case (lw) 2'd3: o3 = w[(kk << 3) + 3]; 2'd2: o3 = w[(kk << 2) + 3]; default: o3 = 1'b0; endcase end
    assign d[3] = o3;
    reg o4; always @* begin o4 = 1'b0; case (lw) 2'd3: o4 = w[(kk << 3) + 4]; default: o4 = 1'b0; endcase end
    assign d[4] = o4;
    reg o5; always @* begin o5 = 1'b0; case (lw) 2'd3: o5 = w[(kk << 3) + 5]; default: o5 = 1'b0; endcase end
    assign d[5] = o5;
    reg o6; always @* begin o6 = 1'b0; case (lw) 2'd3: o6 = w[(kk << 3) + 6]; default: o6 = 1'b0; endcase end
    assign d[6] = o6;
    reg o7; always @* begin o7 = 1'b0; case (lw) 2'd3: o7 = w[(kk << 3) + 7]; default: o7 = 1'b0; endcase end
    assign d[7] = o7;
endmodule

// write accumulator + digit counter: digits are inserted at digit index kk; the last digit of a pass (32/W of them) gives flush = 1 and the whole word on `word`
module sc_wacc8 (input clk, input rst, input [1:0] lw, input en, input [4:0] kk, input [7:0] wd, output flush, output [31:0] word);
    reg [31:0] acc; reg [4:0] cnt;
    wire [4:0] nlast = (lw == 2'd3) ? 5'd3 : (lw == 2'd2) ? 5'd7 : (lw == 2'd1) ? 5'd15 : 5'd31;
    assign flush = en & (cnt == nlast);
    assign word[0] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd0) : (lw == 2'd1) ? (kk == 5'd0) : (kk == 5'd0)) ? (lw == 2'd3) ? wd[0] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[0];
    assign word[1] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd0) : (lw == 2'd1) ? (kk == 5'd0) : (kk == 5'd1)) ? (lw == 2'd3) ? wd[1] : (lw == 2'd2) ? wd[1] : (lw == 2'd1) ? wd[1] : wd[0] : acc[1];
    assign word[2] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd0) : (lw == 2'd1) ? (kk == 5'd1) : (kk == 5'd2)) ? (lw == 2'd3) ? wd[2] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[2];
    assign word[3] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd0) : (lw == 2'd1) ? (kk == 5'd1) : (kk == 5'd3)) ? (lw == 2'd3) ? wd[3] : (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[3];
    assign word[4] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd1) : (lw == 2'd1) ? (kk == 5'd2) : (kk == 5'd4)) ? (lw == 2'd3) ? wd[4] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[4];
    assign word[5] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd1) : (lw == 2'd1) ? (kk == 5'd2) : (kk == 5'd5)) ? (lw == 2'd3) ? wd[5] : (lw == 2'd2) ? wd[1] : (lw == 2'd1) ? wd[1] : wd[0] : acc[5];
    assign word[6] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd1) : (lw == 2'd1) ? (kk == 5'd3) : (kk == 5'd6)) ? (lw == 2'd3) ? wd[6] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[6];
    assign word[7] = (en & (lw == 2'd3) ? (kk == 5'd0) : (lw == 2'd2) ? (kk == 5'd1) : (lw == 2'd1) ? (kk == 5'd3) : (kk == 5'd7)) ? (lw == 2'd3) ? wd[7] : (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[7];
    assign word[8] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd2) : (lw == 2'd1) ? (kk == 5'd4) : (kk == 5'd8)) ? (lw == 2'd3) ? wd[0] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[8];
    assign word[9] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd2) : (lw == 2'd1) ? (kk == 5'd4) : (kk == 5'd9)) ? (lw == 2'd3) ? wd[1] : (lw == 2'd2) ? wd[1] : (lw == 2'd1) ? wd[1] : wd[0] : acc[9];
    assign word[10] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd2) : (lw == 2'd1) ? (kk == 5'd5) : (kk == 5'd10)) ? (lw == 2'd3) ? wd[2] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[10];
    assign word[11] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd2) : (lw == 2'd1) ? (kk == 5'd5) : (kk == 5'd11)) ? (lw == 2'd3) ? wd[3] : (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[11];
    assign word[12] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd3) : (lw == 2'd1) ? (kk == 5'd6) : (kk == 5'd12)) ? (lw == 2'd3) ? wd[4] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[12];
    assign word[13] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd3) : (lw == 2'd1) ? (kk == 5'd6) : (kk == 5'd13)) ? (lw == 2'd3) ? wd[5] : (lw == 2'd2) ? wd[1] : (lw == 2'd1) ? wd[1] : wd[0] : acc[13];
    assign word[14] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd3) : (lw == 2'd1) ? (kk == 5'd7) : (kk == 5'd14)) ? (lw == 2'd3) ? wd[6] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[14];
    assign word[15] = (en & (lw == 2'd3) ? (kk == 5'd1) : (lw == 2'd2) ? (kk == 5'd3) : (lw == 2'd1) ? (kk == 5'd7) : (kk == 5'd15)) ? (lw == 2'd3) ? wd[7] : (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[15];
    assign word[16] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd4) : (lw == 2'd1) ? (kk == 5'd8) : (kk == 5'd16)) ? (lw == 2'd3) ? wd[0] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[16];
    assign word[17] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd4) : (lw == 2'd1) ? (kk == 5'd8) : (kk == 5'd17)) ? (lw == 2'd3) ? wd[1] : (lw == 2'd2) ? wd[1] : (lw == 2'd1) ? wd[1] : wd[0] : acc[17];
    assign word[18] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd4) : (lw == 2'd1) ? (kk == 5'd9) : (kk == 5'd18)) ? (lw == 2'd3) ? wd[2] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[18];
    assign word[19] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd4) : (lw == 2'd1) ? (kk == 5'd9) : (kk == 5'd19)) ? (lw == 2'd3) ? wd[3] : (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[19];
    assign word[20] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd5) : (lw == 2'd1) ? (kk == 5'd10) : (kk == 5'd20)) ? (lw == 2'd3) ? wd[4] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[20];
    assign word[21] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd5) : (lw == 2'd1) ? (kk == 5'd10) : (kk == 5'd21)) ? (lw == 2'd3) ? wd[5] : (lw == 2'd2) ? wd[1] : (lw == 2'd1) ? wd[1] : wd[0] : acc[21];
    assign word[22] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd5) : (lw == 2'd1) ? (kk == 5'd11) : (kk == 5'd22)) ? (lw == 2'd3) ? wd[6] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[22];
    assign word[23] = (en & (lw == 2'd3) ? (kk == 5'd2) : (lw == 2'd2) ? (kk == 5'd5) : (lw == 2'd1) ? (kk == 5'd11) : (kk == 5'd23)) ? (lw == 2'd3) ? wd[7] : (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[23];
    assign word[24] = (en & (lw == 2'd3) ? (kk == 5'd3) : (lw == 2'd2) ? (kk == 5'd6) : (lw == 2'd1) ? (kk == 5'd12) : (kk == 5'd24)) ? (lw == 2'd3) ? wd[0] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[24];
    assign word[25] = (en & (lw == 2'd3) ? (kk == 5'd3) : (lw == 2'd2) ? (kk == 5'd6) : (lw == 2'd1) ? (kk == 5'd12) : (kk == 5'd25)) ? (lw == 2'd3) ? wd[1] : (lw == 2'd2) ? wd[1] : (lw == 2'd1) ? wd[1] : wd[0] : acc[25];
    assign word[26] = (en & (lw == 2'd3) ? (kk == 5'd3) : (lw == 2'd2) ? (kk == 5'd6) : (lw == 2'd1) ? (kk == 5'd13) : (kk == 5'd26)) ? (lw == 2'd3) ? wd[2] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[26];
    assign word[27] = (en & (lw == 2'd3) ? (kk == 5'd3) : (lw == 2'd2) ? (kk == 5'd6) : (lw == 2'd1) ? (kk == 5'd13) : (kk == 5'd27)) ? (lw == 2'd3) ? wd[3] : (lw == 2'd2) ? wd[3] : (lw == 2'd1) ? wd[1] : wd[0] : acc[27];
    assign word[28] = (en & (lw == 2'd3) ? (kk == 5'd3) : (lw == 2'd2) ? (kk == 5'd7) : (lw == 2'd1) ? (kk == 5'd14) : (kk == 5'd28)) ? (lw == 2'd3) ? wd[4] : (lw == 2'd2) ? wd[0] : (lw == 2'd1) ? wd[0] : wd[0] : acc[28];
