    assign word[30] = (en & (lw == 2'd3) ? (kk == 5'd3) : (lw == 2'd2) ? (kk == 5'd7) : (lw == 2'd1) ? (kk == 5'd15) : (kk == 5'd30)) ? (lw == 2'd3) ? wd[6] : (lw == 2'd2) ? wd[2] : (lw == 2'd1) ? wd[0] : wd[0] : acc[30];
