endmodule

module uc_unitw8 (
    input  wire              clk,
    input  wire              rst,
    input  wire [1:0]        lw,
    input  wire              start,
    input  wire [31:0]       entry,
    input  wire              ce,
    input  wire              abort,
    input  wire              dblk,           // a data store is blocked (region check of the slice): it is not accumulated
    output wire              halted,
    output wire              trap,
    output wire              fetching,
    output wire              dmem_act,
    output wire              dmem_ld,
    output wire [29:0]       imem_addr,
    input  wire [31:0]       imem_data,
    // register file: whole words, two read ports, one word write port
    output wire [4:0]        ra_wa,
    input  wire [31:0]       ra_word,
    output wire [4:0]        rb_wa,
    input  wire [31:0]       rb_word,
    output wire              rw_we,
    output wire [4:0]        rw_wa,
    output wire [31:0]       rw_word,
    // data memory: whole words
    output wire [29:0]       d_wa,
    input  wire [31:0]       d_word,
    output wire              d_wwe,
    output wire [31:0]       d_wword
);
    wire [9:0]  ra_addr, rb_addr, rw_addr;
    wire [7:0] ra_data, rb_data, rw_data, d_wdata, d_rdata;
    wire        rw_en, d_we;
    wire [34:0] d_addr;
    uc_unith8 core (.clk(clk), .rst(rst), .lw(lw), .start(start), .entry(entry), .ce(ce), .abort(abort), .halted(halted), .trap(trap), .fetching(fetching), .dmem_act(dmem_act), .dmem_ld(dmem_ld), .imem_addr(imem_addr), .imem_data(imem_data),
        .ra_addr(ra_addr), .ra_data(ra_data), .rb_addr(rb_addr), .rb_data(rb_data),
        .rw_en(rw_en), .rw_addr(rw_addr), .rw_data(rw_data),
        .d_addr(d_addr), .d_we(d_we), .d_wdata(d_wdata), .d_rdata(d_rdata));
    assign ra_wa = ra_addr[9:5]; assign rb_wa = rb_addr[9:5];
    sc_rdsel8 sa (.w(ra_word), .kk(ra_addr[4:0]), .lw(lw), .d(ra_data));
    sc_rdsel8 sb (.w(rb_word), .kk(rb_addr[4:0]), .lw(lw), .d(rb_data));
    sc_rdsel8 sd (.w(d_word),  .kk(d_addr[4:0]),  .lw(lw), .d(d_rdata));
    assign rw_wa = rw_addr[9:5];
    assign d_wa  = d_addr[34:5];
    sc_wacc8 wr (.clk(clk), .rst(rst | start), .lw(lw), .en(rw_en & ce), .kk(rw_addr[4:0]), .wd(rw_data), .flush(rw_we), .word(rw_word));
    sc_wacc8 wd (.clk(clk), .rst(rst | start), .lw(lw), .en(d_we & ce & ~dblk),  .kk(d_addr[4:0]),  .wd(d_wdata), .flush(d_wwe), .word(d_wword));
endmodule
